"""`docs/index.html` is the index of every doc, generated by `make docs` with the YAML
reference: it is current, every `docs/*.md` is in exactly one group of `GROUPS` with
its first heading and the start of its first paragraph, and every link it holds is
relative and reaches a file of the repository. Every test file a doc, `CLAUDE.md`, a
rule or a skill names exists, so a test that moved is never looked for where it was.
"""

import os
import re
import sys

import pytest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

from scripts.keiko.yamldoc import DOCS, INDEX, docs_index, main, write  # noqa: E402
from scripts.keiko.yamldoc.index import (  # noqa: E402
    REFERENCE,
    SUMMARY_LENGTH,
    Group,
    index,
    read_doc,
    summary,
    unplaced,
)
from scripts.keiko.yamldoc.page import slug  # noqa: E402

from app.core.commands import YAML_TYPES  # noqa: E402

pytestmark = pytest.mark.unit

THINGS = """\
# Adding a `thing`

> A dated record: a note above the text, not its summary.

| a | b |
|---|---|

```
# a comment in a block, not a heading
```

One thing is **one** folder (`app/things/`), see [the guide](guide.md). Everything
else lives there. And this third sentence never reaches the card.

## Next
"""


TEST_PATH = re.compile(r"tests/[\w./-]*\w")

EXAMPLE_TEST = "tests/test_greet.py"


def _markdown_files() -> list[str]:
    return sorted(path.name for path in DOCS.glob("*.md"))


def _guides() -> list:
    root = DOCS.parent
    found = [*DOCS.glob("**/*.md"), root / "CLAUDE.md"]
    found += [*root.glob(".claude/rules/*.md"), *root.glob(".claude/skills/*/SKILL.md")]
    return sorted(found)


def _dated(text: str) -> bool:
    """A dated record keeps the paths of its day, as its opening note says."""
    parts = text.split("\n\n", 2)
    return len(parts) > 1 and parts[1].startswith("> A dated record")


def _test_paths(text: str) -> list[str]:
    """Every test path the text names, placeholders (`test_<module>.py`) left out."""
    named = []
    for match in TEST_PATH.finditer(text):
        after = text[match.end() : match.end() + 2].lstrip("/")
        if after[:1] not in ("<", "*", "{"):
            named.append(match.group(0))
    return named


def test_the_docs_index_is_current():
    page = DOCS / INDEX
    current = page.read_text(encoding="utf-8") if page.exists() else ""

    assert current == docs_index(), "docs/index.html is stale: run make docs"


def test_every_doc_is_in_exactly_one_group():
    assert unplaced(_markdown_files()) == []


def test_a_doc_in_no_group_is_refused():
    docs = {"guide.md": "# Guide\n\nHow.\n", "new.md": "# New\n\nWhat.\n"}
    groups = (Group("Guides", "How.", ("guide.md", REFERENCE)),)

    with pytest.raises(ValueError, match="docs/new.md is in no group: add it to"):
        index(docs, YAML_TYPES, groups)


def test_a_doc_listed_twice_or_gone_is_refused():
    groups = (
        Group("Guides", "How.", ("guide.md", "gone.md")),
        Group("Histories", "When.", ("guide.md",)),
    )

    assert unplaced(["guide.md"], groups) == [
        "docs/guide.md is in 2 groups",
        "docs/gone.md is listed but does not exist",
    ]


def test_a_doc_without_a_heading_is_refused():
    with pytest.raises(ValueError, match="docs/loose.md has no `# ` heading"):
        read_doc("loose.md", "Only text.\n")


def test_a_card_reads_the_first_heading_and_the_first_paragraph():
    doc = read_doc("things.md", THINGS)

    assert doc.title == "Adding a `thing`"
    assert doc.summary == (
        "One thing is one folder, see the guide. Everything else lives there."
    )


def test_a_long_first_sentence_is_cut_at_a_word_and_never_inside_code():
    long = "Start " + "word " * 33 + "`make command name=greet` and more words."

    cut = summary(long)

    assert cut.endswith("…")
    assert len(cut) <= SUMMARY_LENGTH
    assert "`" not in cut


def test_every_doc_and_the_reference_have_a_card():
    page = (DOCS / INDEX).read_text(encoding="utf-8")
    titled = re.findall(r'<h3><a href="([^"]+)">', page)

    assert sorted(titled) == sorted([*_markdown_files(), REFERENCE])


def test_every_link_of_the_index_is_relative_and_reaches_a_file():
    page = (DOCS / INDEX).read_text(encoding="utf-8")
    types = {slug(kind.name) for kind in YAML_TYPES}

    for link in re.findall(r'href="([^"]+)"', page):
        path, _, anchor = link.partition("#")
        assert not re.match(r"([a-z]+:|/)", link), f"{link} is not relative"
        assert (DOCS / path).resolve().is_file(), f"{link} reaches no file"
        assert not anchor or (path == REFERENCE and anchor in types), link
    assert not re.search(r"\ssrc=|@import", page), "the index fetches nothing"


def test_the_reference_links_back_to_the_index():
    page = (DOCS / REFERENCE).read_text(encoding="utf-8")

    assert f'href="{INDEX}"' in page


def test_the_check_fails_on_a_stale_page(tmp_path, capsys):
    write(tmp_path)
    assert main(["--check", "--out", str(tmp_path)]) == 0

    (tmp_path / INDEX).write_text("stale", encoding="utf-8")

    assert main(["--check", "--out", str(tmp_path)]) == 1
    assert f"{tmp_path / INDEX} is stale: run make docs" in capsys.readouterr().err


def test_every_test_file_a_doc_names_exists():
    root = DOCS.parent
    gone = [
        f"{doc.relative_to(root)}: {path}"
        for doc in _guides()
        if not _dated(text := doc.read_text(encoding="utf-8"))
        for path in _test_paths(text)
        if path != EXAMPLE_TEST and not (root / path).exists()
    ]

    assert gone == [], f"point each at the test's new home: {gone}"


def test_a_doc_path_is_read_up_to_its_test_and_placeholders_are_skipped():
    text = (
        "pinned by `tests/test_gone.py::test_one`, run `tests/test_<module>.py`, "
        "`tests/core/test_*.py` or `tests/behavioral/flows/<command>.py`, see tests/forms."
    )

    assert _test_paths(text) == ["tests/test_gone.py", "tests/forms"]
    assert _dated(THINGS)
